import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

export default function QuizList() {
  const [quizzes, setQuizzes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchQuizzes = async () => {
      try {
        const token = localStorage.getItem('token');
        const user = JSON.parse(localStorage.getItem('user') || '{}');
        
        if (!token) {
          navigate('/login');
          return;
        }

        setUser(user);
        
        const res = await axios.get('http://localhost:5000/api/quizzes', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setQuizzes(res.data);
      } catch (err) {
        console.error('Failed to load quizzes:', err);
        if (err.response?.status === 401) {
          localStorage.removeItem('token');
          localStorage.removeItem('user');
          navigate('/login');
        }
      } finally {
        setLoading(false);
      }
    };

    fetchQuizzes();
  }, [navigate]);

  const handleAdminDashboard = () => {
    navigate('/admin');
  };

  if (loading) {
    return <div className="container mt-4">Loading quizzes...</div>;
  }

  return (
    <div className="container mt-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h1>Available Quizzes</h1>
        {user?.role === 'admin' && (
          <button 
            className="btn btn-primary"
            onClick={handleAdminDashboard}
          >
            Admin Dashboard
          </button>
        )}
      </div>

      {quizzes.length === 0 ? (
        <div className="text-center">
          <p className="text-muted">No quizzes available yet.</p>
          {user?.role === 'admin' && (
            <p>Go to Admin Dashboard to create quizzes.</p>
          )}
        </div>
      ) : (
        <div className="row">
          {quizzes.map(quiz => (
            <div key={quiz._id} className="col-md-6 col-lg-4 mb-4">
              <div className="card h-100">
                <div className="card-body d-flex flex-column">
                  <h5 className="card-title">{quiz.title}</h5>
                  <p className="card-text">
                    <strong>Subject:</strong> {quiz.subject}<br/>
                    <strong>Questions:</strong> {quiz.totalQuestions}<br/>
                    <strong>Total Marks:</strong> {quiz.totalMarks}<br/>
                    <strong>Time Limit:</strong> {Math.floor(quiz.timeLimit / 60)} minutes
                  </p>
                  <div className="mt-auto">
                    <Link 
                      to={`/quiz/${quiz._id}`} 
                      className="btn btn-primary w-100"
                    >
                      Take Quiz
                    </Link>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
